import {useState, type ReactNode} from 'react';
import { Outlet, useNavigate, useLocation } from 'react-router-dom';
import { Sparkles, BarChart3, ScrollText, BookOpen, FileText, Clock, X } from 'lucide-react';
import { cn } from '../../lib/cn';

const aiNavItems = [
  { id: 'ai', label: 'AI Dashboard', icon: Sparkles, path: '/app/ai' },
  { id: 'ai-history', label: 'History', icon: Clock, path: '/app/ai/history' },
  { id: 'ai-analytics', label: 'Analytics AI', icon: BarChart3, path: '/app/ai/analytics' },
  { id: 'ai-handover', label: 'Handover AI', icon: ScrollText, path: '/app/ai/handover' },
  { id: 'ai-knowledge', label: 'Knowledge AI', icon: BookOpen, path: '/app/ai/knowledge' },
  { id: 'ai-reports', label: 'Report Viewer', icon: FileText, path: '/app/ai/reports' },
];

export function AILayout() {
  const navigate = useNavigate();
  const location = useLocation();
  const [sidebarOpen, setSidebarOpen] = useState(false);

  const isActive = (path: string) => location.pathname === path;

  return (
    <div className="flex gap-0 lg:gap-6">
      {/* Mobile sidebar trigger */}
      <button
        type="button"
        onClick={() => setSidebarOpen(true)}
        aria-label="Open AI navigation"
        aria-expanded={sidebarOpen}
        aria-haspopup="dialog"
        className="lg:hidden fixed bottom-6 right-6 z-50 flex h-12 w-12 items-center justify-center rounded-full bg-accent-600 text-white shadow-cx-lg hover:bg-accent-700 transition-colors"
      >
        <Sparkles className="h-5 w-5" />
      </button>

      {/* Mobile backdrop */}
      {sidebarOpen && (
        <div className="fixed inset-0 z-40 bg-text-primary/40 dark:bg-black/60 backdrop-blur-sm animate-fade-in lg:hidden" aria-hidden="true" onClick={() => setSidebarOpen(false)} />
      )}

      {/* AI Sidebar navigation */}
      <div
        role={sidebarOpen ? 'dialog' : undefined}
        aria-modal={sidebarOpen ? 'true' : undefined}
        aria-label="AI navigation"
        className={cn(
          'fixed inset-y-0 left-0 z-50 w-64 shrink-0 bg-elevated border-r border-border-subtle overflow-y-auto transition-transform duration-300 lg:sticky lg:top-0 lg:z-0 lg:block lg:h-[calc(100vh-7rem)] lg:border lg:border-border-subtle lg:rounded-xl lg:bg-surface',
          sidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0',
        )}
      >
        <div className="flex items-center justify-between px-4 py-4 lg:hidden">
          <div className="flex items-center gap-2">
            <Sparkles className="h-5 w-5 text-accent-600" />
            <p className="text-section font-semibold text-text-primary">Collabix AI</p>
          </div>
          <button
            type="button"
            onClick={() => setSidebarOpen(false)}
            aria-label="Close AI navigation"
            className="flex h-8 w-8 items-center justify-center rounded-lg text-text-tertiary hover:bg-surface-2 hover:text-text-primary transition-colors"
          >
            <X className="h-4 w-4" />
          </button>
        </div>

        <div className="p-3 hidden lg:block">
          <div className="flex items-center gap-2 px-2 py-3">
            <Sparkles className="h-5 w-5 text-accent-600 dark:text-accent-400" />
            <p className="text-section font-semibold text-text-primary">Collabix AI</p>
          </div>
        </div>

        <nav aria-label="AI sections" className="px-2 pb-4">
          {aiNavItems.map((item) => {
            const Icon = item.icon;
            const active = isActive(item.path);
            return (
              <button
                key={item.id}
                type="button"
                onClick={() => { navigate(item.path); setSidebarOpen(false); }}
                className={cn(
                  'flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-body transition-colors text-left',
                  active
                    ? 'bg-accent-600/10 text-accent-700 dark:bg-accent-100/15 dark:text-accent-200 font-medium'
                    : 'text-text-secondary hover:bg-surface-2 hover:text-text-primary',
                )}
              >
                <Icon className={cn('h-4 w-4 shrink-0', active && 'text-accent-600 dark:text-accent-300')} />
                <span className="flex-1">{item.label}</span>
              </button>
            );
          })}
        </nav>
      </div>

      {/* Main content area */}
      <div className="flex-1 min-w-0 flex flex-col gap-6">
        <Outlet />
      </div>

      {/* Contextual right panel (prepared for future features) */}
      {rightPanelOpen && (
        <div className="hidden lg:block w-72 shrink-0 border border-border-subtle rounded-xl bg-surface overflow-y-auto h-[calc(100vh-7rem)] sticky top-0 p-4">
          <p className="text-caption font-medium text-text-tertiary">Context Panel</p>
          <p className="text-body text-text-secondary mt-2">
            AI context and suggestions will appear here.
          </p>
        </div>
      )}
    </div>
  );
}

import {useEffect, useRef} from 'react';
import {X, Calendar, Clock, MapPin, Users, Briefcase, Building2, FolderKanban} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { cn } from '../../lib/cn';
import { IconButton } from '../ui/IconButton';
import { Badge } from '../ui/Badge';
import { eventCategoryConfig, type CalendarEvent } from './CalendarTypes';

interface CalendarEventDrawerProps {
  event: CalendarEvent | null;
  open: boolean;
  onClose: () => void;
}

export function CalendarEventDrawer({ event, open, onClose }: CalendarEventDrawerProps) {
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') onClose(); };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [open, onClose]);

  useEffect(() => {
    if (open) ref.current?.focus();
  }, [open]);

  if (!event) return null;

  const cfg = eventCategoryConfig[event.category];

  return (
    <>
      {open && (
        <div className="fixed inset-0 z-40 bg-text-primary/30 dark:bg-black/50 backdrop-blur-sm animate-fade-in" onClick={onClose} />
      )}
      <div
        ref={ref} role="dialog" aria-modal="true" aria-label={`Event: ${event.title}`} tabIndex={-1}
        className={cn(
          'fixed right-0 top-0 z-50 h-full w-full max-w-lg border-l border-border-subtle bg-elevated shadow-cx-xl transition-transform duration-300 flex flex-col',
          open ? 'translate-x-0' : 'translate-x-full',
        )}
      >
        <div className="flex items-center justify-between px-5 py-4 border-b border-border-subtle">
          <p className="text-section font-semibold text-text-primary">Event Details</p>
          <IconButton label="Close" variant="ghost" size="sm" onClick={onClose}>
            <X className="h-4 w-4" />
          </IconButton>
        </div>

        <div className="flex-1 overflow-y-auto px-5 py-5 space-y-6">
          <div className="space-y-2">
            <Badge variant="soft" tone={cfg.color.includes('danger') ? 'danger' : cfg.color.includes('success') ? 'success' : cfg.color.includes('warning') ? 'warning' : 'accent'}>{cfg.label}</Badge>
            <p className="text-body-lg font-semibold text-text-primary">{event.title}</p>
            {event.description && <p className="text-body text-text-secondary leading-relaxed">{event.description}</p>}
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div className="rounded-lg bg-surface p-3">
              <div className="flex items-center gap-2 text-caption text-text-tertiary mb-1"><Calendar className="h-3.5 w-3.5" /><span>Date</span></div>
              <p className="text-caption font-medium text-text-primary">{event.date}</p>
            </div>
            {event.startTime && (
              <div className="rounded-lg bg-surface p-3">
                <div className="flex items-center gap-2 text-caption text-text-tertiary mb-1"><Clock className="h-3.5 w-3.5" /><span>Time</span></div>
                <p className="text-caption font-medium text-text-primary">{event.startTime}{event.endTime ? ` - ${event.endTime}` : ''}</p>
              </div>
            )}
            {event.location && (
              <div className="rounded-lg bg-surface p-3">
                <div className="flex items-center gap-2 text-caption text-text-tertiary mb-1"><MapPin className="h-3.5 w-3.5" /><span>Location</span></div>
                <p className="text-caption font-medium text-text-primary">{event.location}</p>
              </div>
            )}
            {event.workspace && (
              <div className="rounded-lg bg-surface p-3">
                <div className="flex items-center gap-2 text-caption text-text-tertiary mb-1"><Briefcase className="h-3.5 w-3.5" /><span>Workspace</span></div>
                <p className="text-caption font-medium text-text-primary">{event.workspace}</p>
              </div>
            )}
            {event.department && (
              <div className="rounded-lg bg-surface p-3">
                <div className="flex items-center gap-2 text-caption text-text-tertiary mb-1"><Building2 className="h-3.5 w-3.5" /><span>Department</span></div>
                <p className="text-caption font-medium text-text-primary">{event.department}</p>
              </div>
            )}
            {event.project && (
              <div className="rounded-lg bg-surface p-3">
                <div className="flex items-center gap-2 text-caption text-text-tertiary mb-1"><FolderKanban className="h-3.5 w-3.5" /><span>Project</span></div>
                <p className="text-caption font-medium text-text-primary">{event.project}</p>
              </div>
            )}
          </div>

          {event.participants && event.participants.length > 0 && (
            <div className="space-y-2">
              <div className="flex items-center gap-2 text-caption text-text-tertiary"><Users className="h-3.5 w-3.5" /><span className="font-semibold text-text-primary">Participants</span></div>
              <div className="flex flex-wrap gap-2">{event.participants.map((p) => (<Badge key={p} variant="soft" tone="neutral">{p}</Badge>))}</div>
            </div>
          )}
        </div>
      </div>
    </>
  );
}

import { FileText, Download, Copy, Share2, ExternalLink, ChevronLeft, ChevronRight } from 'lucide-react';
import { cn } from '../../lib/cn';
import { IconButton } from '../ui/IconButton';
import { Badge } from '../ui/Badge';
import {fileTypeConfig, type PreviewFile, type FileType} from './FilePreviewTypes';

interface FilePreviewToolbarProps {
  file: PreviewFile;
  onZoomIn?: () => void;
  onZoomOut?: () => void;
  onRotate?: () => void;
  onFullscreen?: () => void;
  onCopyLink?: () => void;
  onDownload?: () => void;
  onShare?: () => void;
  onPrev?: () => void;
  onNext?: () => void;
  hasPrev?: boolean;
  hasNext?: boolean;
}

export function FilePreviewToolbar({
  file, onZoomIn, onZoomOut, onRotate, onFullscreen,
  onCopyLink, onDownload, onShare, onPrev, onNext,
  hasPrev, hasNext,
}: FilePreviewToolbarProps) {
  const cfg = fileTypeConfig[file.type];

  return (
    <div className="flex items-center justify-between gap-2 border-b border-border-subtle bg-elevated px-4 py-2.5">
      <div className="flex items-center gap-2 min-w-0">
        <span className={cn('flex h-8 w-8 shrink-0 items-center justify-center rounded-lg', cfg.color)}>
          <FileText className="h-4 w-4" />
        </span>
        <div className="min-w-0">
          <p className="text-caption font-medium text-text-primary truncate">{file.name}.{file.extension}</p>
          <div className="flex items-center gap-2 text-2xs text-text-tertiary">
            <Badge variant="soft" tone="neutral" className="text-2xs">{cfg.label.toUpperCase()}</Badge>
            <span>{file.size}</span>
          </div>
        </div>
      </div>

      <div className="flex items-center gap-1">
        <div className="hidden sm:flex items-center gap-1 mr-2">
          <IconButton label="Previous file" variant="ghost" size="sm" onClick={onPrev} disabled={!hasPrev}>
            <ChevronLeft className="h-4 w-4" />
          </IconButton>
          <IconButton label="Next file" variant="ghost" size="sm" onClick={onNext} disabled={!hasNext}>
            <ChevronRight className="h-4 w-4" />
          </IconButton>
          <span className="mx-1 h-5 w-px bg-border-subtle" />
        </div>
        <IconButton label="Zoom in" variant="ghost" size="sm" onClick={onZoomIn}><SearchPlusIcon /></IconButton>
        <IconButton label="Zoom out" variant="ghost" size="sm" onClick={onZoomOut}><SearchMinusIcon /></IconButton>
        <IconButton label="Rotate" variant="ghost" size="sm" onClick={onRotate}><RotateIcon /></IconButton>
        <IconButton label="Fullscreen" variant="ghost" size="sm" onClick={onFullscreen}><ExternalLink className="h-4 w-4" /></IconButton>
        <span className="mx-1 h-5 w-px bg-border-subtle" />
        <IconButton label="Copy link" variant="ghost" size="sm" onClick={onCopyLink}><Copy className="h-4 w-4" /></IconButton>
        <IconButton label="Download" variant="ghost" size="sm" onClick={onDownload}><Download className="h-4 w-4" /></IconButton>
        <IconButton label="Share" variant="ghost" size="sm" onClick={onShare}><Share2 className="h-4 w-4" /></IconButton>
      </div>
    </div>
  );
}

function SearchPlusIcon() {
  return (
    <svg className="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <circle cx="11" cy="11" r="8" /><line x1="21" y1="21" x2="16.65" y2="16.65" /><line x1="11" y1="8" x2="11" y2="14" /><line x1="8" y1="11" x2="14" y2="11" />
    </svg>
  );
}

function SearchMinusIcon() {
  return (
    <svg className="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <circle cx="11" cy="11" r="8" /><line x1="21" y1="21" x2="16.65" y2="16.65" /><line x1="8" y1="11" x2="14" y2="11" />
    </svg>
  );
}

function RotateIcon() {
  return (
    <svg className="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <polyline points="23 4 23 10 17 10" /><path d="M20.49 15a9 9 0 11-2.12-9.36L23 10" />
    </svg>
  );
}

import { useState, useMemo, type ReactNode } from 'react';
import { useSearchParams } from 'react-router-dom';
import {
  LayoutGrid,
  FolderKanban,
  CheckSquare,
  FileText,
  BookOpen,
  Bell,
  BarChart3,
  Users,
  Settings,
  ChevronLeft,
  ChevronRight,
  ChevronDown,
  ScrollText,
  Building2,
  Network,
  MessageSquare,
  X,
  Briefcase,
  LayoutList,
  Plus,
  Shield,
  Lock,
  Sparkles,
  Activity,
  CalendarDays,
  Archive,
  Hash,
  Search,
  CalendarClock,
  GraduationCap,
  ClipboardCheck,
  Star,
  Clock,
} from 'lucide-react';
import { cn } from '../../lib/cn';
import { useAuth } from '../../lib/auth-context';
import { useUnreadCount } from '../../services/notification-hooks';
import { isHrDepartment, HR_TAB_IDS } from '../../lib/hr';

export interface NavItem {
  id: string;
  label: string;
  icon: ReactNode;
  badge?: number;
  children?: NavItem[];
}

export interface SidebarProps {
  collapsed: boolean;
  onToggle: () => void;
  activeId: string;
  onNavigate: (id: string) => void;
}

