function isItemActive(item: NavItem, activeId: string): boolean {
  if (item.id === activeId) return true;
  if (item.children?.some((c) => c.id === activeId) ?? false) return true;
  if (item.id.startsWith('hr:') && activeId === 'departments') return true;
  return false;
}

const HR_ICONS = {
  dashboard: <LayoutGrid />,
  employees: <Users />,
  candidates: <Briefcase />,
  interviews: <CalendarClock />,
  skills: <GraduationCap />,
  onboarding: <ClipboardCheck />,
  reviews: <Star />,
  attendance: <Clock />,
  documents: <FileText />,
  notifications: <Bell />,
} as const;

function buildHrSection(departmentId: string, departmentName: string | undefined): { title: string; items: NavItem[] } {
  return {
    title: 'HR Management',
    items: [
      {
        id: `hr:${departmentId}`,
        label: departmentName ?? 'Human Resources',
        icon: <Users />,
        children: HR_TAB_IDS.map((tab) => ({
          id: `hr:${departmentId}:${tab}`,
          label: tab.charAt(0).toUpperCase() + tab.slice(1),
          icon: HR_ICONS[tab],
        })),
      },
    ],
  };
}

function NavLink({
  item,
  collapsed,
  activeId,
  onNavigate,
  expandedSections,
  setExpandedSections,
}: {
  item: NavItem;
  collapsed: boolean;
  activeId: string;
  onNavigate: (id: string) => void;
  expandedSections: Record<string, boolean>;
  setExpandedSections: (id: string, v: boolean) => void;
}) {
  const isActive = isItemActive(item, activeId);
  const hasChildren = !!item.children?.length;
  const isExpandable = item.id === 'projects' || item.id === 'organization' || item.id === 'workspace' || item.id === 'admin' || item.id.startsWith('hr:');
  const isExpanded = expandedSections[item.id] ?? true;

  if (hasChildren && isExpandable) {
    return (
      <div className="w-full">
        <button
          type="button"
          onClick={() => !collapsed && setExpandedSections(item.id, !isExpanded)}
          title={collapsed ? item.label : undefined}
          className={cn(
            'group flex w-full items-center gap-3 rounded-lg px-2.5 py-2 text-body font-medium transition-all duration-150 ease-cx',
            'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent-500',
            isActive
              ? 'bg-accent-50 text-accent-700 dark:bg-accent-100 dark:text-accent-200'
              : 'text-text-secondary hover:bg-surface-2 hover:text-text-primary',
            collapsed && 'justify-center',
          )}
        >
          <span className={cn('shrink-0 [&>svg]:h-[18px] [&>svg]:w-[18px]', isActive && 'text-accent-600 dark:text-accent-300')}>
            {item.icon}
          </span>
          {!collapsed && (
            <>
              <span className="flex-1 text-left truncate">{item.label}</span>
              <ChevronDown
                className={cn(
                  'h-4 w-4 text-text-tertiary transition-transform duration-150',
                  isExpanded && 'rotate-180',
                )}
              />
            </>
          )}
        </button>
        {!collapsed && isExpanded && (
          <nav className="mt-0.5 ml-3 flex flex-col gap-0.5 border-l border-border-subtle pl-3 animate-fade-in">
            {item.children!.map((child) => {
              const childActive = child.id === activeId;
              return (
                <button
                  key={child.id}
                  type="button"
                  onClick={() => onNavigate(child.id)}
                  className={cn(
                    'flex items-center gap-2.5 rounded-lg px-2.5 py-1.5 text-body transition-all duration-150 ease-cx',
                    'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent-500',
                    childActive
                      ? 'bg-accent-50 text-accent-700 dark:bg-accent-100 dark:text-accent-200 font-medium'
                      : 'text-text-tertiary hover:bg-surface-2 hover:text-text-primary',
                  )}
                >
                  <span className="shrink-0 [&>svg]:h-4 [&>svg]:w-4">{child.icon}</span>
                  <span className="text-left truncate">{child.label}</span>
                </button>
              );
            })}
          </nav>
        )}
      </div>
    );
  }

  return (
    <button
      type="button"
      onClick={() => onNavigate(item.id)}
      title={collapsed ? item.label : undefined}
      className={cn(
        'group flex w-full items-center gap-3 rounded-lg px-2.5 py-2 text-body font-medium transition-all duration-150 ease-cx',
        'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent-500',
        isActive
          ? 'bg-accent-50 text-accent-700 dark:bg-accent-100 dark:text-accent-200'
          : 'text-text-secondary hover:bg-surface-2 hover:text-text-primary',
        collapsed && 'justify-center',
      )}
    >
      <span className={cn('shrink-0 [&>svg]:h-[18px] [&>svg]:w-[18px]', isActive && 'text-accent-600 dark:text-accent-300')}>
        {item.icon}
      </span>
      {!collapsed && (
        <>
