function SidebarContent({
  collapsed,
  activeId,
  onNavigate,
  expandedSections,
  setExpandedSections,
}: {
  collapsed: boolean;
  activeId: string;
  onNavigate: (id: string) => void;
  expandedSections: Record<string, boolean>;
  setExpandedSections: (id: string, v: boolean) => void;
}) {
  const { user } = useAuth();
  const isAdmin = user?.roles?.some((r) => r === 'SUPER_ADMIN' || r === 'ADMIN');
  const isManager = user?.roles?.includes('MANAGER') ?? false;
  const perms = user?.permissions ?? [];
  const [searchParams] = useSearchParams();
  const wsId = searchParams.get('ws') ?? '';
  const { data: notifCount } = useUnreadCount(wsId);

  const visibleSections = useMemo(() => {
    const sections = navSections
      .map((section) => {
        if (section.title === 'Administration' && !isAdmin) return null;

        const filteredItems = section.items
          .map((item) => {
            if (item.id === 'admin' && !isAdmin) return null;
            if (item.id === 'workspace' && isManager) return null;
            if (item.id === 'create-workspace' && !perms.includes('WORKSPACE_CREATE')) return null;
            if (item.id === 'settings' && (isManager || !perms.includes('WORKSPACE_UPDATE'))) return null;

            let badge = item.badge;
            if (item.id === 'notifications' && notifCount !== undefined) {
              badge = notifCount;
            }

            if (item.children) {
              const filteredChildren = item.children.filter((child) => {
                if (child.id === 'create-workspace' && !perms.includes('WORKSPACE_CREATE')) return false;
                if (isManager && ['workspace-overview', 'workspace-members', 'workspace-activity', 'workspace-analytics', 'workspace-reports', 'all-workspaces', 'archived-workspaces', 'create-workspace'].includes(child.id)) return false;
                return true;
              });
              return { ...item, children: filteredChildren, badge };
            }

            return { ...item, badge };
          })
          .filter(Boolean) as NavItem[];

        if (filteredItems.length === 0) return null;
        return { ...section, items: filteredItems };
      })
      .filter(Boolean) as typeof navSections;

    if (user?.departmentId) {
      const isHR = isHrDepartment(user.departmentName ?? '');
      if (isManager && isHR) {
        sections.splice(1, 0, buildHrSection(user.departmentId, user.departmentName));
      } else {
        sections.splice(1, 0, {
          title: 'My Department',
          items: [{
            id: `department:${user.departmentId}`,
            label: user.departmentName ?? 'My Department',
            icon: <Building2 />,
          }],
        });
      }
    }

    return sections;
  }, [isAdmin, isManager, perms, notifCount, user?.departmentId, user?.departmentName]);

  const tabParam = searchParams.get('tab');
  const deepActiveId =
    activeId === 'departments' && user?.departmentId
      ? `hr:${user.departmentId}:${HR_TAB_IDS.includes(tabParam as (typeof HR_TAB_IDS)[number]) ? tabParam : 'dashboard'}`
      : activeId;

  return (
    <div className="flex-1 overflow-y-auto py-3 flex flex-col gap-4">
      {visibleSections.map((section, si) => (
        <div key={si} className="px-3">
          {!collapsed && section.title && (
            <p className="px-2 py-2 text-2xs font-semibold uppercase tracking-wider text-text-tertiary">
              {section.title}
            </p>
          )}
          <nav className="flex flex-col gap-0.5">
            {section.items.map((item) => (
              <NavLink
                key={item.id}
                item={item}
                collapsed={collapsed}
                activeId={deepActiveId}
                onNavigate={onNavigate}
                expandedSections={expandedSections}
                setExpandedSections={setExpandedSections}
              />
            ))}
          </nav>
        </div>
      ))}
    </div>
  );
}

