import { useState, useRef, useEffect, useMemo } from 'react';
import { useParams, useSearchParams } from 'react-router-dom';
import {Send, Paperclip, Pin, MoreHorizontal, UserPlus, Hash, Loader2} from 'lucide-react';
import { Button } from '../../components/ui/Button';
import { Input } from '../../components/ui/Input';
import { Avatar } from '../../components/ui/Avatar';
import { IconButton } from '../../components/ui/IconButton';
import { EmptyState } from '../../components/ui/EmptyState';
import { cn } from '../../lib/cn';
import { useConversationDetail, useConversationMembers } from '../../services/conversation-hooks';
import { useMessages, useCreateMessage, useUpdateMessage, usePinnedMessages } from '../../services/message-hooks';
import { formatRelativeTime } from '../../lib/format';
import type { MessageResponse } from '../../types/communication';

export function ChatWindow() {
  const { conversationId } = useParams();
  const [searchParams] = useSearchParams();
  const wsId = searchParams.get('ws') ?? '';
  const [newMessage, setNewMessage] = useState('');
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  const { data: conversation, isLoading: convLoading } = useConversationDetail(wsId, conversationId);
  const {data: members} = useConversationMembers(wsId, conversationId ?? '');
  const { data: pinnedData } = usePinnedMessages(wsId, conversationId ?? '');
  const { data: messagesPages, isLoading: msgsLoading, fetchNextPage, hasNextPage } = useMessages(wsId, conversationId ?? '');
  const createMessage = useCreateMessage(wsId, conversationId ?? '');
  const updateMessage = useUpdateMessage(wsId, conversationId ?? '');

  const handleTogglePin = async (message: MessageResponse) => {
    if (!conversationId) return;
    try {
      await updateMessage.mutateAsync({ msgId: message.id, data: { isPinned: !message.isPinned } });
    } catch {
      // handled by mutation
    }
  };

  const messages = useMemo(() => {
    if (!messagesPages?.pages) return [];
    return messagesPages.pages.flatMap((p) => p.content);
  }, [messagesPages]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages.length]);

  const handleSend = async () => {
    if (!newMessage.trim() || !conversationId) return;
    try {
      await createMessage.mutateAsync({ content: newMessage.trim() });
      setNewMessage('');
      inputRef.current?.focus();
    } catch {
      // handled by mutation
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  if (convLoading) {
    return (
      <div className="flex items-center justify-center py-20">
        <Loader2 className="h-6 w-6 animate-spin text-text-tertiary" />
      </div>
    );
  }

  if (!conversation) {
    return (
      <EmptyState
        icon={<Hash className="h-8 w-8" />}
        title="Select a conversation"
        description="Choose a channel or direct message from the list."
      />
    );
  }

  return (
    <div className="flex h-full flex-col rounded-xl border border-border-subtle bg-elevated">
      <div className="flex items-center justify-between border-b border-border-subtle px-4 py-3">
        <div className="flex items-center gap-3">
          <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-accent-50 text-accent-600 dark:bg-accent-100 dark:text-accent-300">
            {conversation.isPrivate ? <UserPlus className="h-4 w-4" /> : <Hash className="h-4 w-4" />}
          </div>
          <div>
            <p className="text-body font-semibold text-text-primary">{conversation.name}</p>
            <p className="text-caption text-text-tertiary">{conversation.memberCount} members</p>
          </div>
        </div>
        <div className="flex items-center gap-1">
          {pinnedData && pinnedData.length > 0 && (
            <IconButton label={`${pinnedData.length} pinned messages`}>
              <Pin className="h-4 w-4" />
            </IconButton>
          )}
          <IconButton label="More options">
            <MoreHorizontal className="h-4 w-4" />
          </IconButton>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto px-4 py-4 space-y-3">
        {hasNextPage && (
          <div className="flex justify-center">
            <Button variant="ghost" size="sm" onClick={() => fetchNextPage()}>
              Load older messages
            </Button>
          </div>
        )}

        {msgsLoading && messages.length === 0 ? (
          <div className="flex items-center justify-center py-10">
            <Loader2 className="h-5 w-5 animate-spin text-text-tertiary" />
          </div>
        ) : messages.length === 0 ? (
          <div className="flex items-center justify-center py-10">
            <p className="text-caption text-text-tertiary">No messages yet. Start the conversation!</p>
          </div>
        ) : (
          messages.map((msg) => (
            <MessageBubble key={msg.id} message={msg} onTogglePin={() => handleTogglePin(msg)} />
          ))
        )}
        <div ref={messagesEndRef} />
      </div>

      <div className="border-t border-border-subtle px-4 py-3">
        <div className="flex items-center gap-2">
          <IconButton label="Attach file">
            <Paperclip className="h-4 w-4" />
          </IconButton>
          <div className="flex-1">
            <Input
              ref={inputRef}
              placeholder={`Message #${conversation.name}`}
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              onKeyDown={handleKeyDown}
            />
          </div>
          <Button
            variant="primary"
            size="sm"
            onClick={handleSend}
            disabled={!newMessage.trim() || createMessage.isPending}
          >
            {createMessage.isPending ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : (
              <Send className="h-4 w-4" />
            )}
          </Button>
        </div>
      </div>
    </div>
  );
}

function MessageBubble({ message, onTogglePin }: { message: MessageResponse; onTogglePin?: () => void }) {
  const isDeleted = message.status === 'DELETED';

  return (
    <div className={cn('flex items-start gap-3 group', isDeleted && 'opacity-50')}>
      <Avatar
        src={message.senderProfilePicture}
        name={`${message.senderFirstName} ${message.senderLastName}`}
        size="sm"
      />
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-2">
          <span className="text-body font-semibold text-text-primary">
            {message.senderFirstName} {message.senderLastName}
          </span>
          <span className="text-2xs text-text-tertiary">
            {formatRelativeTime(message.createdAt)}
          </span>
          {message.status === 'EDITED' && (
            <span className="text-2xs text-text-tertiary">(edited)</span>
          )}
          {message.isPinned && (
            <Pin className="h-3 w-3 text-amber-500" />
          )}
          {onTogglePin && !isDeleted && (
            <button
              type="button"
              onClick={onTogglePin}
              title={message.isPinned ? 'Unpin message' : 'Pin message'}
              className="ml-auto text-text-tertiary opacity-0 transition-opacity group-hover:opacity-100 hover:text-amber-500"
            >
              <Pin className="h-3.5 w-3.5" />
            </button>
          )}
        </div>
        <p className={cn(
          'text-body text-text-primary mt-0.5',
          isDeleted && 'italic text-text-tertiary',
        )}>
          {message.content}
        </p>
        {message.fileUrl && (
          <div className="mt-2 rounded-lg border border-border-subtle bg-surface-2 p-3">
            <p className="text-caption font-medium text-text-primary">{message.fileName}</p>
            {message.mimeType?.startsWith('image/') && (
              <img src={message.fileUrl} alt={message.fileName ?? ''} className="mt-2 max-h-48 rounded object-contain" />
            )}
          </div>
        )}
      </div>
    </div>
  );
}

import { useState } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import {FileText, Image, File, Download} from 'lucide-react';
import { Card, CardBody } from '../../components/ui/Card';
import { EmptyState } from '../../components/ui/EmptyState';
import { Button } from '../../components/ui/Button';
import { cn } from '../../lib/cn';
import { useConversationFiles, useWorkspaceMessageFiles } from '../../services/message-hooks';
import { useConversationsList } from '../../services/conversation-hooks';
import { Avatar } from '../../components/ui/Avatar';
import { formatRelativeTime, formatFileSize } from '../../lib/format';

export function SharedFiles() {
  const [searchParams] = useSearchParams();
  const wsId = searchParams.get('ws') ?? '';
  const [selectedConvId, setSelectedConvId] = useState<string | undefined>();

  const { data: conversations } = useConversationsList(wsId);
  const convFiles = useConversationFiles(wsId, selectedConvId ?? '');
  const wsFiles = useWorkspaceMessageFiles(wsId);
  const filesData = selectedConvId ? convFiles.data : wsFiles.data;

  const files = filesData?.content ?? [];
  const [filter, setFilter] = useState<'all' | 'images' | 'documents'>('all');

  const filteredFiles = files.filter((f) => {
    if (filter === 'images') return f.mimeType?.startsWith('image/');
    if (filter === 'documents') return f.mimeType && !f.mimeType.startsWith('image/');
    return true;
  });

  return (
    <div className="flex flex-col gap-4">
      <div className="flex items-center gap-4">
        <div className="flex gap-2">
          <button
            type="button"
            onClick={() => setFilter('all')}
            className={cn('rounded-lg px-3 py-1.5 text-body font-medium transition-colors', filter === 'all' ? 'bg-accent-50 text-accent-700 dark:bg-accent-100 dark:text-accent-200' : 'text-text-tertiary hover:text-text-primary')}
          >
            All
          </button>
          <button
            type="button"
            onClick={() => setFilter('images')}
            className={cn('rounded-lg px-3 py-1.5 text-body font-medium transition-colors', filter === 'images' ? 'bg-accent-50 text-accent-700 dark:bg-accent-100 dark:text-accent-200' : 'text-text-tertiary hover:text-text-primary')}
          >
            <Image className="mr-1.5 inline h-4 w-4" />
            Images
          </button>
          <button
            type="button"
            onClick={() => setFilter('documents')}
            className={cn('rounded-lg px-3 py-1.5 text-body font-medium transition-colors', filter === 'documents' ? 'bg-accent-50 text-accent-700 dark:bg-accent-100 dark:text-accent-200' : 'text-text-tertiary hover:text-text-primary')}
          >
            <FileText className="mr-1.5 inline h-4 w-4" />
            Documents
          </button>
        </div>
        {conversations && conversations.content.length > 0 && (
          <select
            value={selectedConvId ?? ''}
            onChange={(e) => setSelectedConvId(e.target.value || undefined)}
            className="rounded-lg border border-border-subtle bg-elevated px-3 py-1.5 text-body text-text-primary"
          >
            <option value="">All Channels</option>
            {conversations.content.map((conv) => (
              <option key={conv.id} value={conv.id}>{conv.name}</option>
            ))}
          </select>
        )}
      </div>

      <Card>
        <CardBody>
          {filteredFiles.length === 0 ? (
            <EmptyState
              icon={<FileText className="h-8 w-8" />}
              title="No shared files"
              description="Files shared in conversations will appear here."
            />
          ) : (
            <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-3">
              {filteredFiles.map((msg) => (
                <Card key={msg.id}>
                  <CardBody className="p-3">
                    {msg.mimeType?.startsWith('image/') && msg.fileUrl ? (
                      <img src={msg.fileUrl} alt={msg.fileName ?? ''} className="w-full h-32 object-cover rounded-lg mb-2" />
                    ) : (
                      <div className="flex h-32 items-center justify-center rounded-lg bg-surface-2 mb-2">
                        <File className="h-8 w-8 text-text-tertiary" />
                      </div>
                    )}
                    <p className="text-body font-medium text-text-primary truncate">{msg.fileName ?? 'Untitled'}</p>
                    <div className="flex items-center justify-between mt-1">
                      <span className="text-2xs text-text-tertiary">
                        {msg.fileSize ? formatFileSize(msg.fileSize) : ''}
                        {' ┬À '}
                        {formatRelativeTime(msg.createdAt)}
                      </span>
                      <Button variant="ghost" size="sm" onClick={() => window.open(msg.fileUrl, '_blank')}>
                        <Download className="h-3.5 w-3.5" />
                      </Button>
                    </div>
                    <div className="flex items-center gap-1.5 mt-2 text-2xs text-text-tertiary">
                      <Avatar
                        src={msg.senderProfilePicture}
                        name={`${msg.senderFirstName} ${msg.senderLastName}`}
                        size="xs"
                      />
                      {msg.senderFirstName} {msg.senderLastName}
                    </div>
                  </CardBody>
                </Card>
              ))}
            </div>
          )}
        </CardBody>
      </Card>
    </div>
  );
}

import {useState, useEffect, useRef, type FormEvent} from 'react';
import { Upload, FileText, Archive, Trash2, RotateCcw, AlertTriangle } from 'lucide-react';
import { Modal } from '../../../components/ui/Modal';
import { Input } from '../../../components/ui/Input';
import { Textarea } from '../../../components/ui/Textarea';
import { Button } from '../../../components/ui/Button';
import {
  useUploadDocument,
  useUpdateDocument,
  useDeleteDocument,
  useArchiveDocument,
  useRestoreDocument,
} from '../../../services/document-hooks';
import type { DocumentResponse } from '../types/document-types';
import { formatFileSize } from '../types/document-types';

/* ------------------------------------------------------------------ */
/*  UploadDocumentModal                                                */
/* ------------------------------------------------------------------ */

export interface UploadDocumentModalProps {
  isOpen: boolean;
  onClose: () => void;
  wsId: string;
  deptId: string;
  projId: string;
}

export function UploadDocumentModal({ isOpen, onClose, wsId, deptId, projId }: UploadDocumentModalProps) {
  const uploadMutation = useUploadDocument(wsId, deptId, projId);
  const [file, setFile] = useState<File | null>(null);
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [category, setCategory] = useState('');
  const [tags, setTags] = useState('');
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isOpen) {
      setFile(null);
      setTitle('');
      setDescription('');
      setCategory('');
      setTags('');
      setError(null);
    }
  }, [isOpen]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const selected = e.target.files?.[0] ?? null;
    setFile(selected);
    setError(null);
  };

  const handleSubmit = async () => {
    if (!file) {
      setError('Please select a file to upload.');
      return;
    }
    setError(null);
    try {
      await uploadMutation.mutateAsync({
        file,
        title: title.trim() || undefined,
        description: description.trim() || undefined,
        category: category.trim() || undefined,
        tags: tags.trim() || undefined,
      });
      onClose();
    } catch {
      setError('Failed to upload document. Please try again.');
    }
  };

  return (
    <Modal
      open={isOpen}
      onClose={onClose}
      title="Upload Document"
      description="Select a file and provide optional metadata."
      size="md"
      footer={
        <div className="flex justify-end gap-2">
          <Button variant="outline" onClick={onClose}>Cancel</Button>
          <Button onClick={handleSubmit} disabled={!file || uploadMutation.isPending} leftIcon={<Upload className="h-4 w-4" />}>
            {uploadMutation.isPending ? 'Uploading...' : 'Upload'}
          </Button>
        </div>
      }
    >
      <div className="flex flex-col gap-4">
        <div>
          <label className="mb-1.5 block text-caption font-medium text-text-secondary">File *</label>
          <input
            ref={fileInputRef}
            type="file"
            onChange={handleFileChange}
            className="block w-full text-caption text-text-secondary file:mr-3 file:rounded-lg file:border-0 file:bg-accent-50 file:px-3 file:py-1.5 file:text-caption file:font-medium file:text-accent-700 dark:file:bg-accent-100/10 dark:file:text-accent-400"
          />
          {file && (
            <div className="mt-2 flex items-center gap-2 rounded-lg border border-border-subtle bg-surface-2 px-3 py-2">
              <FileText className="h-4 w-4 shrink-0 text-text-tertiary" />
              <div className="min-w-0 flex-1 truncate text-caption text-text-primary">{file.name}</div>
              <div className="shrink-0 text-2xs text-text-tertiary">{formatFileSize(file.size)}</div>
            </div>
          )}
        </div>
        <Input label="Title" value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Optional document title" />
        <Textarea label="Description" value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Optional description" rows={3} />
        <div className="grid grid-cols-2 gap-4">
          <Input label="Category" value={category} onChange={(e) => setCategory(e.target.value)} placeholder="e.g. Reports" />
          <Input label="Tags" value={tags} onChange={(e) => setTags(e.target.value)} placeholder="Comma-separated" />
        </div>
