import { useMemo } from 'react';
import { useQueries, useQuery } from '@tanstack/react-query';
import { useWorkspaceId } from '../../hooks/useWorkspaceId';
import { useDepartmentList } from '../../services/department-hooks';
import type { TeamSummary } from '../../services/team-service';
import { listTeamsByDepartment } from '../../services/team-service';

export function useTeamsData() {
  const wsId = useWorkspaceId();
  const { data: deptList, isLoading: deptLoading } = useDepartmentList(wsId);

  const departmentIds = (deptList ?? []).map((d) => d.id);
  const departmentMap = useMemo(() => {
    const map: Record<string, string> = {};
    (deptList ?? []).forEach((d) => {
      map[d.id] = d.name;
    });
    return map;
  }, [deptList]);

  const teamQueries = useQueries({
    queries: departmentIds.map((deptId) => ({
      queryKey: ['teams', wsId, deptId],
      queryFn: () => listTeamsByDepartment(wsId, deptId),
      enabled: !!wsId && !!deptId,
      staleTime: 30000,
    })),
  });

  const isLoading = deptLoading || teamQueries.some((q) => q.isLoading);
  const isError = teamQueries.some((q) => q.isError);

  const teams = useMemo(() => {
    const allTeams: (TeamSummary & { departmentName: string; departmentId: string })[] = [];
    teamQueries.forEach((q, index) => {
      const deptId = departmentIds[index];
      const deptName = departmentMap[deptId] ?? '';
      if (q.data) {
        q.data.forEach((t) => {
          allTeams.push({ ...t, departmentName: deptName, departmentId: deptId });
        });
      }
    });
    return allTeams;
  }, [teamQueries, departmentIds, departmentMap]);

  const departments = useMemo(() => (deptList ?? []).map((d) => d.name), [deptList]);

  return { teams, departments, departmentMap, isLoading, isError };
}

